<?php
namespace App\Domain\Capabilities; use App\Models\Capability; final class CapabilityDependencyInspector { public function inspect(Capability $capability):array{$navigation=$capability->navigationItems()->where('is_active',true)->count();$homepage=$capability->homepageItems()->where('is_active',true)->count();$industryNeeds=$capability->industryNeeds()->where('is_active',true)->whereHas('industry',fn($q)=>$q->publiclyVisible())->count();$relations=$capability->relatedSolutions()->publiclyVisible()->count()+$capability->relatedProducts()->publiclyVisible()->count()+$capability->relatedIndustries()->publiclyVisible()->count()+$capability->relatedPages()->publiclyVisible()->count();return ['navigation'=>$navigation,'homepage'=>$homepage,'industry_needs'=>$industryNeeds,'relations'=>$relations,'children'=>$capability->highlights()->count()+$capability->benefits()->count()+$capability->facts()->count(),'blocked'=>$navigation+$homepage+$industryNeeds+$relations>0];} }
